INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (351871, 14548, 'South China Morning Post', 'en', 'US Attorney General Blanche defends colleague after Trump’s reflecting pool slam', 'https://www.scmp.com/news/world/united-states-canada/article/3364221/attorney-general-blanche-publicly-backs-pirro-after-trump-criticism-over-reflecting-pool', 'US Attorney General Todd Blanche said ⁠on Sunday that ⁠he backs top Washington prosecutor ⁠Jeanine Pirro, who was criticised by US President Donald Trump for the way she handled a case of alleged vandalism at the Lincoln Memorial Reflecting Pool. “I absolutely support US Attorney Pirro, as does President Trump,” Blanche said ‌on NBC’s Meet the Press programme. The Trump administration fast-tracked a renovation of the Lincoln Memorial Reflecting Pool ahead of the nation’s Fourth of July...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/17/a554cd25-b842-4b12-bee8-9ccf0de85ed2_9937b115.jpg?itok=O6Bfulma&v=1786913603', '2026-08-16T20:55:04+00:00', '2026-08-16T22:07:41.652371'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (351877, 14548, 'South China Morning Post', 'en', 'BBC asks US court for help with testimony from the Trump family in defamation suit', 'https://www.scmp.com/news/world/europe/article/3364214/bbc-asks-us-court-help-testimony-trump-family-defamation-suit', 'Britain’s BBC asked a US court for help in getting documents and testimony from members of US President Donald Trump’s family in connection with his US$10-billion defamation lawsuit against the British broadcaster, a court document showed. Lawyers for the BBC argued that Ivanka Trump, her husband Jared Kushner and Donald Trump Jnr have “personal knowledge” and are likely to have records relevant to elements of Trump’s claims against the broadcaster, according to a filing on Friday in federal...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/17/d83e6d5b-4a11-44ad-88cf-142a4445c8ef_e303c744.jpg?itok=9YD1w2eC&v=1786898519', '2026-08-16T16:45:18+00:00', '2026-08-16T22:07:41.814405'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (329381, 14549, 'The Guardian', 'en', 'BP to develop offshore gasfield in Venezuela with firms linked to Trump administration', 'https://www.theguardian.com/business/2026/aug/14/bp-offshore-gasfield-venezuela-donald-trump', 'Move will be one of first large-scale foreign investments in country since US ousted leader Nicolás Maduro in January BP has answered Donald Trump’s call for oil companies to help rebuild Venezuela’s fossil fuel industry with new plans to develop a large offshore gasfield. BP will partner with two oil firms with close links to the Trump administration to develop the second phase of the Loran gasfield, in one of the first large-scale foreign investments in Venezuela since the US ousted its leader Nicolás Maduro in January. Continue reading...', 'https://i.guim.co.uk/img/media/8f7d2b49b727e55d0f750fcf85afdd20aac8e3d7/338_27_2589_2072/master/2589.jpg?width=140&quality=85&auto=format&fit=max&s=44cb171b3bae1a37488d77c5030abf31', '2026-08-14T14:04:49+00:00', '2026-08-14T14:58:19.526740'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
