INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (329385, 14551, 'The Guardian', 'en', 'Lending to property investors falls sharply in ‘tiny’ step towards fairer housing market in Australia, expert says', 'https://www.theguardian.com/australia-news/2026/aug/14/lending-to-property-investors-falls-sharply-in-tiny-step-towards-fairer-housing-market-in-australia-expert-says', 'ABS data shows an almost 9% slump in new lending to investors after three interest rate hikes this year Follow our Australia news live blog for latest updates Get our breaking news email , free app or daily news podcast In what one economist is describing as a “tiny step” toward a fairer housing market after decades of bad policy, property investors are shying away from established homes, and putting money into new builds instead, new data shows. New lending to property investors fell sharply in the three months to June, slumping almost 9%, ABS data showed, while the number of total new home l', 'https://i.guim.co.uk/img/media/e8f789681a7293189635a9594c0c624cb4befb14/569_0_5689_4551/master/5689.jpg?width=140&quality=85&auto=format&fit=max&s=a9a4dd8a2bfaafa63fd805a1478f03e1', '2026-08-14T08:03:29+00:00', '2026-08-14T14:58:19.600628'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
