INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (331247, 14562, 'Le Monde', 'en', 'Constitutional Council approves France''s assisted-dying law', 'https://www.lemonde.fr/en/france/article/2026/08/14/constitutional-council-approves-france-s-assisted-dying-law_6756508_7.html', 'The legislation grants adults suffering from an incurable condition the right to assisted dying. The Council''s decision is a victory for President Emmanuel Macron, who promised such a law when he was re-elected for a second term in 2022.', 'https://img.lemde.fr/2025/08/07/0/0/5271/2635/644/322/60/0/b568b1a_ftp-import-images-1-ewttvogmvpsb-2025-08-07t160305z-1591006970-rc2f2gatf32g-rtrmadp-3-france-agriculture-law.JPG', '2026-08-14T13:42:56+00:00', '2026-08-14T15:01:14.985998'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (331248, 14562, 'Le Monde', 'en', 'France''s Constitutional Council strikes down social media ban for under-15s', 'https://www.lemonde.fr/en/pixels/article/2026/08/14/france-s-constitutional-council-strikes-down-ban-on-social-media-for-under-15s_6756507_13.html', 'The Council said the ban ''constitutes a restriction that is not appropriate, necessary or proportionate'' to the freedom of expression of children under 15. President Emmanuel Macron, a staunch promoter of the ban, asked his prime minister to work on a new ''legally robust draft.''', 'https://img.lemde.fr/2026/07/23/0/0/5000/2500/644/322/60/0/e791e90_upload-1-wa98lajizx3r-080-hl-nguyonnet-3239035.jpg', '2026-08-14T13:10:25+00:00', '2026-08-14T15:01:14.998649'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
