INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (333435, 14562, 'Al Jazeera English', 'en', 'Top French court upholds assisted dying law, rejects teen social media ban', 'https://www.aljazeera.com/news/2026/8/14/top-french-court-upholds-assisted-dying-law-rejects-teen-social-media-ban?traffic_source=rss', 'The decisions mark both a victory and a setback for President Emmanuel Macron, who had championed both policies.', '', '2026-08-14T15:52:57+00:00', '2026-08-14T17:15:55.713924'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (333472, 14562, 'France 24', 'en', 'France blocks under 15 social media ban', 'https://www.france24.com/en/france-blocks-under-15-social-media-ban', 'France’s Constitutional Council has blocked a bill that would have banned social media access for under-15s, ruling that it infringed on freedom of expression. It’s a setback for President Emmanuel Macron, who has championed the legislation and has now asked his prime minister to rewrite the bill. The Élysée says Macron remains determined to have the reform in place before next year’s presidential election. France 24 International Affairs editor tells us more.', 'https://s.france24.com/media/display/ed52f104-97f3-11f1-9975-005056bfb2b6/w:1024/p:16x9/EN-20260814-170741-171130-CS.jpg', '2026-08-14T15:25:17+00:00', '2026-08-14T17:16:16.186418'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
