INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (333678, 14568, 'The Hindu BusinessLine', 'en', 'Robust accretion to FCNR-B deposits: RBI decides to pull the plug on concessional swap facility', 'https://www.thehindubusinessline.com/money-and-banking/robust-accretion-to-fcnr-b-deposits-rbi-decides-to-pull-the-plug-on-concessional-swap-facility/article71346259.ece', 'The concessional swap facility will now be available only for FCNR(B) deposits of 3-5 years maturity mobilised till August 31, against the earlier deadline of September 30', 'https://bl-i.thgim.com/public/incoming/euon99/article71346539.ece/alternates/LANDSCAPE_1200/2025-02-27T185919Z_424006808_RC253DAB1XHI_RTRMADP_3_USA-JUNKBONDS-PRIVATEEQUITY.JPG', '2026-08-14T15:23:08+00:00', '2026-08-14T17:17:47.654287'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
