INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (353967, 14568, 'The Economic Times', 'en', 'Rupee faces pressure as RBI defends 95.45 against dollar amid rising crude oil prices', 'https://economictimes.indiatimes.com/markets/forex/forex-news/rupee-faces-pressure-as-rbi-defends-95-45-against-dollar-amid-rising-crude-oil-prices/articleshow/133284217.cms', 'The Reserve Bank of India is defending the rupee at 95.45 against the dollar. Traders are closely watching crude oil prices amid West Asia crisis concerns. Dollar demand from importers and oil companies is expected to increase significantly. The FCNR(B) deposit drive''s final stretch may offer some rupee support. The rupee''s movement depends on RBI intervention and cooling oil prices.', 'https://img.etimg.com/photo/msid-133284217,imgsize-16982.cms', '2026-08-17T00:38:07+00:00', '2026-08-17T01:32:18.823454'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (353973, 14568, 'The Economic Times', 'en', 'RBI moves to distance self from bank deposit ratings', 'https://economictimes.indiatimes.com/markets/stocks/news/rbi-moves-to-distance-self-from-bank-deposit-ratings/articleshow/133284278.cms', 'The Reserve Bank of India has instructed rating agencies to refrain from categorizing it as the regulator overseeing bank deposits. This recent directive raises the possibility that these credit assessment organizations may halt the evaluation of bank deposits entirely. With threats of deposit outflows and potential bank instability stemming from any downgraded ratings, the landscape of retail deposit reactions remains mixed.', 'https://img.etimg.com/photo/msid-133284278,imgsize-116014.cms', '2026-08-16T19:16:08+00:00', '2026-08-17T01:32:18.971039'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
