INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (356004, 14568, 'The Hindu BusinessLine', 'en', 'Indian bonds may slip after RBI shortens swap window for diaspora deposits', 'https://www.thehindubusinessline.com/markets/indian-bonds-may-slip-after-rbi-shortens-swap-window-for-diaspora-deposits/article71354808.ece', 'Yield ⁠on the benchmark 6.94% 2036 bond may hover in the 6.75% to 6.78% range, private-bank trader says', 'https://bl-i.thgim.com/public/incoming/tb31sb/article71354840.ece/alternates/LANDSCAPE_1200/IMG_BL02_Government_bond_2_1_Q98EFHHC.jpg', '2026-08-17T03:42:54+00:00', '2026-08-17T04:37:55.399764'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (356297, 14568, 'The Hindu', 'en', 'Rupee falls 17 paise to 95.59 against U.S. dollar in early trade', 'https://www.thehindu.com/business/markets/rupee-falls-17-paise-to-9559-against-us-dollar-in-early-trade/article71354941.ece', 'At the interbank foreign exchange, the rupee opened at 95.50, then fell to 95.59, down 17 paise from its previous close.', 'https://th-i.thgim.com/public/incoming/dhni63/article71354963.ece/alternates/LANDSCAPE_1200/iStock-2260029287%202.jpg', '2026-08-17T04:53:18+00:00', '2026-08-17T05:36:08.249084'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (356321, 14568, 'The Times of India', 'en', 'Rupee falls 17 paise against US dollar as FCNR swap deadline weighs down sentiment', 'https://timesofindia.indiatimes.com/business/india-business/rupee-falls-17-paise-to-95-59-against-us-dollar-as-fcnr-swap-deadline-weighs-down-sentiment/articleshow/133286610.cms', 'The Indian rupee fell against the US dollar at the start of Monday, influenced by the Reserve Bank of India''s move to advance a deposit swap deadline. While the bank had previously drawn in substantial foreign currency, analysts predict temporary support for the rupee, though overall weakness is expected. Additionally, domestic stock markets recorded a drop early in the trading session.', 'https://static.toiimg.com/photo/msid-133286726,imgsize-81104.cms', '2026-08-17T04:34:13+00:00', '2026-08-17T05:36:34.230584'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
